command:
if [[ -L lib || -L test || -L lib/{module}.pl || ( -e lib/{module}.pl && ! -f lib/{module}.pl ) ]]; then printf 'scaffold: ruta de Perl no segura / unsafe Perl path
' >&2; false; else mkdir -p lib test && { test -e lib/{module}.pl || (set -C; printf 'package {Module};

use strict;
use warnings;

1;
' > lib/{module}.pl); }; fi

composer init -n --name={module}/{module} && composer require --dev --no-update phpunit/phpunit && mkdir -p src test && printf '<?php

declare(strict_types=1);
' > src/{Module}.php && touch phpunit.xml .gitignore
